script:
frappe.ui.form.on("Overtime Slip", {
    refresh(frm) {
        toggle_manual_edit(frm);
    },

    custom_manually_edit_hours(frm) {
        toggle_manual_edit(frm);

        if (frm.doc.custom_manually_edit_hours) {
            update_total(frm);
        }
    },

    custom_total_peak_overtime_hours(frm) {
        update_total(frm);
    },

    custom_total_holiday_overtime_hours(frm) {
        update_total(frm);
    }
});

function toggle_manual_edit(frm) {
    frm.set_df_property(
        "total_overtime_duration",
        "read_only",
        !frm.doc.custom_manually_edit_hours
    );
}

function update_total(frm) {
    // Calculate only when manual edit is enabled
    if (frm.doc.custom_manually_edit_hours) {
        let total =
            (flt(frm.doc.custom_total_peak_overtime_hours) || 0) +
            (flt(frm.doc.custom_total_holiday_overtime_hours) || 0);

        frm.set_value("total_overtime_duration", total);
    }
}
